 40→  if (isNavigating) {
 41→    return (
 42→      <SkeletonPage primaryAction>
 43→        <Layout>
 44→          <Layout.Section>
 45→            <Card>
 46→              <SkeletonDisplayText size="small" />
 47→              <SkeletonBodyText lines={3} />
 48→            </Card>
 49→          </Layout.Section>
 50→          <Layout.Section>
 51→            <Card>
 52→              <SkeletonBodyText lines={6} />
