 68→function ChatwootWidget() {
 69→  useEffect(() => {
 70→    // Skip if already loaded
 71→    if (window.$chatwoot) return;
 72→
 73→    window.chatwootSettings = {
 74→      position: "right",
 75→      type: "standard",
 76→      launcherTitle: "",
 77→    };
 78→
 79→    const BASE_URL = "https://app.chatwoot.com";
 80→    const script = document.createElement("script");
 81→    script.src = `${BASE_URL}/packs/js/sdk.js`;
 82→    script.async = true;
 83→    script.onload = () => {
 84→      window.chatwootSDK?.run({
 85→        websiteToken: "F2gCECkLD25SAkJ92AcVui4x",
 86→        baseUrl: BASE_URL,
 87→      });
 88→    };
 89→    document.body.appendChild(script);
 90→  }, []);
 91→
 92→  return null;
 93→}
