  1→import { useState, useCallback } from "react";
  2→import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
  3→import { useLoaderData, useNavigate, useRevalidator, useRouteError } from "react-router";
  4→import { authenticate } from "../shopify.server";
  5→import { boundary } from "@shopify/shopify-app-react-router/server";
  6→import db from "../db.server";
  7→import { getShopSubscription } from "../billing.server";
  8→import { PLAN_LIMITS, UNLIMITED } from "../plans";
  9→import {
 10→  Page,
 11→  Card,
 12→  BlockStack,
 13→  InlineStack,
 14→  Text,
 15→  Badge,
 16→  Button,
 17→  Banner,
 18→  InlineGrid,
 19→  ProgressBar,
 20→  Box,
 21→  Divider,
 22→  List,
 23→} from "@shopify/polaris";
 24→import { PlusIcon } from "@shopify/polaris-icons";
 25→
 26→export const loader = async ({ request }: LoaderFunctionArgs) => {
 27→  const { session, admin } = await authenticate.admin(request);
 28→  const shop = session.shop;
 29→
 30→  const [totalZips, allowedZips, blockedZips, deliveryRulesCount, waitlistCount, subscription] = await Promise.all([
 31→    db.zipCode.count({ where: { shop } }),
 32→    db.zipCode.count({ where: { shop, type: "allowed" } }),
 33→    db.zipCode.count({ where: { shop, type: "blocked" } }),
 34→    db.deliveryRule.count({ where: { shop } }),
 35→    db.waitlistEntry.count({ where: { shop } }),
 36→    getShopSubscription(shop),
 37→  ]);
 38→
 39→  const stats = {
 40→    total: totalZips,
 41→    allowed: allowedZips,
 42→    blocked: blockedZips,
 43→    deliveryRules: deliveryRulesCount,
 44→    waitlist: waitlistCount,
 45→  };
 46→
 47→  // Detect whether the App Embed is enabled in the active theme (GraphQL)
 48→  let appEmbedEnabled = false;
 49→  let activeThemeName: string | null = null;
 50→  let themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
 51→  let themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/current/editor?context=apps`;
 52→  try {
 53→    const themeResponse = await admin.graphql(`{
 54→      themes(first: 1, roles: MAIN) {
 55→        nodes {
 56→          id
 57→          name
 58→          files(filenames: ["config/settings_data.json"], first: 1) {
 59→            nodes {
 60→              body {
 61→                ... on OnlineStoreThemeFileBodyText {
 62→                  content
 63→                }
 64→              }
 65→            }
 66→          }
 67→        }
 68→      }
 69→    }`);
 70→    const themeData = (await themeResponse.json()) as {
 71→      data?: {
 72→        themes?: {
 73→          nodes?: Array<{
 74→            id: string;
 75→            name: string;
 76→            files?: {
 77→              nodes?: Array<{
 78→                body?: { content?: string };
 79→              }>;
 80→            };
 81→          }>;
 82→        };
 83→      };
 84→    };
 85→    const mainTheme = themeData?.data?.themes?.nodes?.[0];
 86→    if (mainTheme) {
 87→      const gidParts = mainTheme.id.split("/");
 88→      const numericId = gidParts[gidParts.length - 1];
 89→      activeThemeName = mainTheme.name;
 90→      themeEditorUrl = `https://${shop}/admin/themes/${numericId}/editor`;
 91→      themeEditorAppEmbedsUrl = `https://${shop}/admin/themes/${numericId}/editor?context=apps`;
 92→
 93→      let content = mainTheme.files?.nodes?.[0]?.body?.content;
 94→      if (content) {
 95→        /* eslint-disable @typescript-eslint/no-explicit-any */
 96→        // Strip leading comments (some themes prepend CSS/JS comments)
 97→        content = content.replace(/^\/\*[\s\S]*?\*\/\s*/, "").trim();
 98→        // Find the first { to start valid JSON
 99→        const jsonStart = content.indexOf("{");
100→        if (jsonStart > 0) content = content.substring(jsonStart);
101→
102→        let settingsData: any;
103→        try {
104→          settingsData = JSON.parse(content);
105→        } catch {
106→          return {
107→            stats, subscription, appEmbedEnabled, activeThemeName,
108→            themeEditorUrl, themeEditorAppEmbedsUrl,
109→          };
110→        }
111→        const apiKey = process.env.SHOPIFY_API_KEY ?? "";
112→
113→        const blocks = settingsData?.current?.blocks ?? {};
114→        const embedBlocks = Object.entries(blocks).filter(([, block]) => {
115→          const b = block as { type?: string };
116→          const t = b.type ?? "";
117→          return t.includes("app_embed") || t.includes("app-embed");
118→        });
119→
120→        // Check each embed block
121→        for (const [key, block] of embedBlocks) {
122→          const b = block as { type?: string; disabled?: boolean };
123→          if (b.disabled === true) continue;
124→          const typeStr = b.type ?? "";
125→          const keyStr = key;
126→          // Match by API key or app handle
127→          if (
128→            (apiKey && (keyStr.includes(apiKey) || typeStr.includes(apiKey))) ||
129→            keyStr.includes("zip-code") || typeStr.includes("zip-code") ||
130→            keyStr.includes("zip_code") || typeStr.includes("zip_code") ||
131→            keyStr.includes("pinzo") || typeStr.includes("pinzo")
132→          ) {
133→            appEmbedEnabled = true;
134→            break;
135→          }
136→        }
137→
138→        // Fallback: raw string scan
139→        if (!appEmbedEnabled) {
140→          const contentLower = content.toLowerCase();
141→          const hasEmbed = contentLower.includes("app_embed");
142→          const hasOurApp =
143→            (apiKey && contentLower.includes(apiKey.toLowerCase())) ||
144→            contentLower.includes("zip-code-checker") ||
145→            contentLower.includes("zip-code-widget") ||
146→            contentLower.includes("pinzo");
147→          if (hasEmbed && hasOurApp) {
148→            // Check not disabled
149→            const notDisabled = !contentLower.includes('"disabled":true');
150→            if (notDisabled) appEmbedEnabled = true;
151→          }
152→        }
153→
154→        /* eslint-enable @typescript-eslint/no-explicit-any */
155→      }
156→    }
157→  } catch {
158→    // Theme detection failed — leave appEmbedEnabled as false
159→  }
160→
161→  return {
162→    stats,
163→    subscription,
164→    appEmbedEnabled,
165→    activeThemeName,
166→    themeEditorUrl,
167→    themeEditorAppEmbedsUrl,
168→  };
169→};
