 71→export const action = async ({ request }: ActionFunctionArgs) => {
 72→  const { session } = await authenticate.admin(request);
 73→  const shop = session.shop;
 74→  const formData = await request.formData();
 75→  const intent = formData.get("intent");
 76→
 77→  // Fetch email sender settings once for any action that may send emails
 78→  const shopSettings = await db.shopSettings.findUnique({ where: { shop } });
 79→  const emailOpts: EmailOptions = {
 80→    senderName: shopSettings?.emailSenderName,
 81→    shopDisplayName: shopSettings?.shopName,
 82→    replyTo: shopSettings?.emailReplyTo,
 83→  };
 84→
 85→  if (intent === "add") {
 86→    const email = String(formData.get("email") || "").trim().toLowerCase();
 87→    const zipCode = String(formData.get("zipCode") || "")
 88→      .trim()
 89→      .toUpperCase();
 90→    const note = String(formData.get("note") || "").trim() || null;
 91→
 92→    if (!email || !zipCode) return { error: "Email and zip code are required." };
 93→
 94→    const subscription = await getShopSubscription(shop);
 95→    const limits = PLAN_LIMITS[subscription.planTier];
 96→
 97→    if (limits.maxWaitlist === 0) {
 98→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
 99→    }
100→
101→    if (limits.maxWaitlist < UNLIMITED) {
102→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
103→      if (currentCount >= limits.maxWaitlist) {
104→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
105→      }
106→    }
107→
108→    try {
109→      await db.waitlistEntry.create({
110→        data: { shop, email, zipCode, note },
111→      });
112→      return { success: true, action: "added" };
113→    } catch {
114→      return { error: "This email is already on the waitlist for this zip code." };
115→    }
116→  }
117→
118→  if (intent === "delete") {
119→    const id = String(formData.get("id"));
120→    try {
121→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
122→      if (!existing) return { error: "Entry not found." };
123→      await db.waitlistEntry.delete({ where: { id } });
124→      return { success: true, action: "deleted" };
125→    } catch {
126→      return { error: "Failed to delete entry." };
127→    }
128→  }
129→
130→  if (intent === "update-status") {
131→    const id = String(formData.get("id"));
132→    const status = String(formData.get("status"));
133→    try {
134→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
135→      if (!existing) return { error: "Entry not found." };
136→      await db.waitlistEntry.update({ where: { id }, data: { status } });
137→      return { success: true, action: "updated" };
138→    } catch {
139→      return { error: "Failed to update entry status." };
140→    }
141→  }
142→
143→  if (intent === "notify-zip") {
